// Custom Chart.js chart: wrap the sized container, not the bare <canvas>
const { ExportableData } = components;

const chartRows = months.map((month, i) => ({
  Month: month,
  Revenue: revenue[i],
  Target: target[i],
  Attainment: revenue[i] / target[i]   // fraction, not '87%'
}));

<ExportableData
  exportID="revenue-by-month"
  label="Revenue by Month"
  kind="chart"
  rows={chartRows}
  columns={[
    { field: 'Month', label: 'Month', type: 'string' },
    { field: 'Revenue', label: 'Revenue', type: 'currency' },
    { field: 'Target', label: 'Target', type: 'currency' },
    { field: 'Attainment', label: 'Attainment', type: 'percent' }
  ]}
>
  <div style={{ height: 320 }}>
    <canvas ref={canvasRef} />
  </div>
</ExportableData>

// Custom table: export every row that passes the user's filter, in the current sort, not just the visible page
<ExportableData
  exportID="overdue-invoices"
  label="Overdue Invoices"
  kind="table"
  rows={sortedFilteredInvoices}
  columns={[
    { field: 'InvoiceNumber', label: 'Invoice', type: 'string' },
    { field: 'Customer', label: 'Customer', type: 'string' },
    { field: 'DueDate', label: 'Due', type: 'date' },
    { field: 'Balance', label: 'Balance', type: 'currency' }
  ]}
>
  <table>{/* ... */}</table>
</ExportableData>

